#!/bin/sh
# Points the AUR package at a published release: pkgver, pkgrel 1, the tarball's sha256 from
# the release's SHA256SUMS, and .SRCINFO regenerated by makepkg in an archlinux container.
#
#   packaging/aur/update.sh 0.2.1                   # SHA256SUMS from the GitHub release
#   packaging/aur/update.sh 0.2.1 path/to/SHA256SUMS
set -eu

version="${1:?version, e.g. 0.2.1}"
dir="$(cd "$(dirname "$0")/canalis-bin" && pwd)"
sums="${2:-}"
if [ -z "$sums" ]; then
  sums="$(mktemp)"
  trap 'rm -f "$sums"' EXIT
  curl -fsSL -o "$sums" "https://github.com/claritas-audio/canalis/releases/download/v$version/SHA256SUMS"
fi
sha="$(grep "  canalis-$version-x86_64.tar.gz\$" "$sums" | cut -d' ' -f1)"
[ -n "$sha" ] || { echo "no canalis-$version-x86_64.tar.gz in $sums"; exit 1; }

sed -i -e "s/^pkgver=.*/pkgver=$version/" -e "s/^pkgrel=.*/pkgrel=1/" \
  -e "s/^sha256sums=.*/sha256sums=('$sha')/" "$dir/PKGBUILD"
# makepkg refuses root; a throwaway user in the container writes .SRCINFO.
podman run --rm -v "$dir:/pkg:z" docker.io/library/archlinux sh -c \
  'useradd -m b && cp /pkg/PKGBUILD /home/b/ && su b -c "cd && makepkg --printsrcinfo" > /pkg/.SRCINFO'
echo "$dir: canalis-bin $version, sha256 $sha"
